"""The vector index protocol and the hit record it returns."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Protocol

from rag.chunking.base import Chunk


@dataclass(slots=True)
class IndexedHit:
    """One retrieved chunk and why it was retrieved."""

    chunk_id: str
    content: str
    score: float
    metadata: dict[str, Any] = field(default_factory=dict)

    @property
    def document_id(self) -> str:
        return str(self.metadata.get("document_id", ""))

    @property
    def is_demo(self) -> bool:
        return bool(self.metadata.get("is_demo", False))

    @property
    def page_number(self) -> int | None:
        page = self.metadata.get("page_number", -1)
        return None if page in (-1, None) else int(page)

    def citation_label(self) -> str:
        title = str(self.metadata.get("document_title") or self.document_id)
        section = str(self.metadata.get("section_path") or "")
        # section is built as "{document_title} > {heading} > ..." at parse
        # time, so it always starts with the title -- stripping that prefix
        # here is what stops "X > X > Mission" reaching a citation.
        if section.startswith(title):
            section = section[len(title):].lstrip(" >")
        parts = [title]
        if section:
            parts.append(section)
        if self.page_number is not None:
            parts.append(f"page {self.page_number}")
        label = " > ".join(parts)
        return f"{label} [DEMO DATA]" if self.is_demo else label


class VectorIndex(Protocol):
    """Stores chunk vectors and searches them.

    Chunk ids are the same UUIDs PostgreSQL holds, so the index carries no
    truth of its own — it is a derived structure that can be dropped and
    rebuilt from the database at any time.
    """

    name: str

    def add(self, chunks: list[Chunk], vectors: list[list[float]]) -> int: ...

    def search(
        self,
        vector: list[float],
        top_k: int,
        where: dict[str, Any] | None = None,
    ) -> list[IndexedHit]: ...

    def count(self) -> int: ...

    def reset(self) -> None: ...

"""An in-process vector index.

Exists so the whole pipeline — chunk, embed, index, retrieve, assemble context
— can be tested with no Chroma server, no network and no model download. Brute
force cosine over a list, which is fine for a few thousand chunks and hopeless
beyond that, hence Chroma for the real corpus.
"""

from __future__ import annotations

from typing import Any

from rag.chunking.base import Chunk
from rag.indexing.base import IndexedHit


class InMemoryIndex:
    name = "memory"

    def __init__(self) -> None:
        self._vectors: dict[str, list[float]] = {}
        self._content: dict[str, str] = {}
        self._metadata: dict[str, dict[str, Any]] = {}

    def add(self, chunks: list[Chunk], vectors: list[list[float]]) -> int:
        if len(chunks) != len(vectors):
            raise ValueError(f"{len(chunks)} chunks but {len(vectors)} vectors")
        for chunk, vector in zip(chunks, vectors, strict=True):
            self._vectors[chunk.chunk_id] = vector
            self._content[chunk.chunk_id] = chunk.content
            self._metadata[chunk.chunk_id] = chunk.to_metadata()
        return len(chunks)

    def search(
        self,
        vector: list[float],
        top_k: int,
        where: dict[str, Any] | None = None,
    ) -> list[IndexedHit]:
        hits: list[IndexedHit] = []
        for chunk_id, stored in self._vectors.items():
            metadata = self._metadata[chunk_id]
            if where and any(
                metadata.get(key) != value for key, value in where.items()
            ):
                continue
            hits.append(
                IndexedHit(
                    chunk_id=chunk_id,
                    content=self._content[chunk_id],
                    score=_cosine(vector, stored),
                    metadata=metadata,
                )
            )
        hits.sort(key=lambda hit: hit.score, reverse=True)
        return hits[:top_k]

    def count(self) -> int:
        return len(self._vectors)

    def reset(self) -> None:
        self._vectors.clear()
        self._content.clear()
        self._metadata.clear()


def _cosine(a: list[float], b: list[float]) -> float:
    if len(a) != len(b):
        raise ValueError(f"dimension mismatch: {len(a)} vs {len(b)}")
    dot = sum(x * y for x, y in zip(a, b, strict=True))
    # Both embedders normalise, so the dot product is already the cosine. Not
    # re-normalising here keeps a mismatch visible rather than papering over it.
    return float(dot)

"""The categoriser decides what gets filtered at retrieval time, so its rules
are worth pinning down explicitly."""

import pytest

from rag.ingestion.categorise import (
    categorise,
    infer_department,
    is_pdf_url,
    should_skip,
)
from rag.ingestion.models import DocumentCategory


class TestCategorise:
    @pytest.mark.parametrize(
        ("url", "expected"),
        [
            ("https://www.pce.ac.in/accreditation/naac/", DocumentCategory.ACCREDITATION),
            ("https://www.pce.ac.in/accreditation/nirf/", DocumentCategory.ACCREDITATION),
            (
                "https://www.pce.ac.in/bachelors/computer-engineering/curriculum/",
                DocumentCategory.CURRICULUM,
            ),
            ("https://www.pce.ac.in/academics/bachelors/", DocumentCategory.PROGRAMME),
            ("https://admissions.pce.ac.in/faq", DocumentCategory.ADMISSION),
            ("https://www.pce.ac.in/about/the-institute/", DocumentCategory.INSTITUTE_PROFILE),
            ("https://www.pce.ac.in/faculty/directory", DocumentCategory.FACULTY),
            ("https://www.pce.ac.in/library/resources", DocumentCategory.LIBRARY),
            ("https://www.pce.ac.in/research/publications", DocumentCategory.RESEARCH),
            ("https://www.pce.ac.in/students/placements", DocumentCategory.PLACEMENT),
        ],
    )
    def test_known_urls(self, url: str, expected: DocumentCategory) -> None:
        assert categorise(url) == expected

    def test_curriculum_beats_programme(self) -> None:
        """Both patterns match this URL; the more specific rule must win."""
        url = "https://www.pce.ac.in/bachelors/computer-engineering/curriculum/"
        assert categorise(url) is DocumentCategory.CURRICULUM

    def test_unknown_url_is_other(self) -> None:
        assert categorise("https://www.pce.ac.in/something-unmapped/") is DocumentCategory.OTHER


class TestInternalOnlyCategories:
    @pytest.mark.parametrize(
        "category",
        [
            DocumentCategory.INTERNAL_WIKI,
            DocumentCategory.SOP,
            DocumentCategory.CIRCULAR,
            DocumentCategory.LAB_MANUAL,
            DocumentCategory.HELPDESK,
            DocumentCategory.TIMETABLE,
        ],
    )
    def test_internal_categories_are_flagged(self, category: DocumentCategory) -> None:
        assert category.is_internal_only

    @pytest.mark.parametrize(
        "category",
        [DocumentCategory.PROGRAMME, DocumentCategory.FACULTY, DocumentCategory.REPORT],
    )
    def test_public_categories_are_not(self, category: DocumentCategory) -> None:
        assert not category.is_internal_only


class TestDepartment:
    @pytest.mark.parametrize(
        ("url", "expected"),
        [
            ("/bachelors/computer-engineering/", "Computer Engineering"),
            ("/bachelors/information-technology/", "Information Technology"),
            ("/bachelors/automobile-engineering/", "Automobile Engineering"),
            ("/bachelors/mechanical-engineering/", "Mechanical Engineering"),
        ],
    )
    def test_from_url(self, url: str, expected: str) -> None:
        assert infer_department(url) == expected

    def test_electronics_variants_are_distinguished(self) -> None:
        """These two share a prefix; misfiling one under the other would put
        every ECS document in the EXTC filter."""
        assert (
            infer_department("/bachelors/electronics-computer-science/")
            == "Electronics and Computer Science"
        )
        assert (
            infer_department("/bachelors/electronics-and-telecommunication-engineering/")
            == "Electronics and Telecommunication Engineering"
        )

    def test_falls_back_to_text(self) -> None:
        assert (
            infer_department("/some/page", "The Department of Computer Engineering was...")
            == "Computer Engineering"
        )

    def test_ignores_department_mentioned_late_in_a_long_document(self) -> None:
        text = "x" * 5000 + " Department of Mechanical Engineering "
        assert infer_department("/annual-report", text) is None

    def test_returns_none_when_unknown(self) -> None:
        assert infer_department("/about/contact") is None


class TestSkipRules:
    @pytest.mark.parametrize(
        "url",
        [
            "https://www.pce.ac.in/wp-admin/",
            "https://www.pce.ac.in/feed/",
            "https://www.pce.ac.in/tag/news/",
            "https://www.pce.ac.in/page/4",
            "https://www.pce.ac.in/logo.png",
            "https://www.pce.ac.in/style.css",
            "https://www.pce.ac.in/post?replytocom=12",
        ],
    )
    def test_skipped(self, url: str) -> None:
        assert should_skip(url)

    @pytest.mark.parametrize(
        "url",
        [
            "https://www.pce.ac.in/about/the-institute/",
            "https://www.pce.ac.in/report.pdf",
        ],
    )
    def test_not_skipped(self, url: str) -> None:
        assert not should_skip(url)

    def test_docx_is_skipped_but_pdf_is_not(self) -> None:
        """PDFs are the point of the crawl; Word files are not worth parsing."""
        assert should_skip("https://www.pce.ac.in/x.docx")
        assert not should_skip("https://www.pce.ac.in/x.pdf")


def test_is_pdf_url() -> None:
    assert is_pdf_url("https://www.pce.ac.in/annual-report.pdf")
    # The query string is not part of the path, so this is still a PDF.
    assert is_pdf_url("https://www.pce.ac.in/a.PDF?download=1")
    assert not is_pdf_url("https://www.pce.ac.in/about/")


class TestStaticAssetsWithQueryStrings:
    """WordPress appends ?ver=... to every stylesheet and script. Matching the
    extension against the whole URL let all of them through the filter."""

    @pytest.mark.parametrize(
        "url",
        [
            "https://www.pce.ac.in/wp-includes/css/dashicons.min.css?ver=6.9.7",
            "https://www.pce.ac.in/wp-includes/js/jquery.js?ver=3.7.1",
            "https://www.pce.ac.in/uploads/logo.png?v=2",
        ],
    )
    def test_cache_busted_assets_are_skipped(self, url: str) -> None:
        assert should_skip(url)

    def test_a_pdf_with_a_query_string_is_still_crawled(self) -> None:
        assert not should_skip("https://www.pce.ac.in/report.pdf?download=1")

"""ParsedDocument.validate() is the gate that keeps unlabelled or
unprovenanced material out of the corpus. These tests are the reason to trust
the is_demo flag downstream."""

from rag.ingestion.models import (
    DocumentCategory,
    ParsedDocument,
    Section,
    SourceType,
    compute_content_hash,
    slugify,
)


def _document(**overrides: object) -> ParsedDocument:
    defaults: dict[str, object] = {
        "doc_id": "pce-about",
        "title": "About the Institute",
        "source_type": SourceType.WEB_HTML,
        "category": DocumentCategory.INSTITUTE_PROFILE,
        "text": "Established in 1999 under the Mahatma Education Society.",
        "source_url": "https://www.pce.ac.in/about/the-institute/",
    }
    defaults.update(overrides)
    return ParsedDocument(**defaults)  # type: ignore[arg-type]


class TestValidation:
    def test_a_well_formed_document_passes(self) -> None:
        assert _document().validate() == []

    def test_a_document_with_no_provenance_fails(self) -> None:
        problems = _document(source_url=None, local_path=None).validate()
        assert any("provenance" in p for p in problems)

    def test_demo_without_a_reason_fails(self) -> None:
        problems = _document(is_demo=True, category=DocumentCategory.SOP).validate()
        assert any("demo_reason" in p for p in problems)

    def test_internal_only_category_marked_real_fails(self) -> None:
        """An SOP claiming to be public data is the exact mistake that would
        make the 80/20 split meaningless."""
        problems = _document(category=DocumentCategory.SOP, is_demo=False).validate()
        assert any("internal-only" in p for p in problems)

    def test_internal_only_category_marked_demo_passes(self) -> None:
        document = _document(
            category=DocumentCategory.SOP,
            is_demo=True,
            demo_reason="Internal procedures are never published publicly.",
        )
        assert document.validate() == []

    def test_pdf_without_page_numbers_fails(self) -> None:
        """Page-level provenance is a project requirement, not a nicety."""
        document = _document(
            source_type=SourceType.WEB_PDF,
            sections=[Section(heading="A", level=1, content="x" * 60, order_index=0)],
        )
        assert any("page numbers" in p for p in document.validate())

    def test_pdf_with_page_numbers_passes(self) -> None:
        document = _document(
            source_type=SourceType.WEB_PDF,
            sections=[
                Section(
                    heading="A",
                    level=1,
                    content="x" * 60,
                    order_index=0,
                    start_page=3,
                    end_page=4,
                )
            ],
        )
        assert document.validate() == []

    def test_empty_text_fails(self) -> None:
        assert any("text is empty" in p for p in _document(text="   ").validate())


class TestDefaults:
    def test_fetched_at_and_hash_are_filled_in(self) -> None:
        document = _document()
        assert document.fetched_at
        assert len(document.content_hash) == 64

    def test_word_count(self) -> None:
        assert _document(text="one two three").word_count == 3


class TestContentHash:
    def test_is_stable(self) -> None:
        assert compute_content_hash("Hello world") == compute_content_hash("Hello world")

    def test_ignores_whitespace_and_case(self) -> None:
        """A page whose sidebar reflowed has not changed its content."""
        assert compute_content_hash("Hello   world\n") == compute_content_hash("hello world")

    def test_detects_a_real_change(self) -> None:
        assert compute_content_hash("Intake is 180") != compute_content_hash("Intake is 120")


class TestSlugify:
    def test_basic(self) -> None:
        assert slugify("About The Institute!") == "about-the-institute"

    def test_truncates_without_a_trailing_hyphen(self) -> None:
        assert not slugify("word " * 60, max_length=20).endswith("-")

    def test_empty_input_has_a_fallback(self) -> None:
        assert slugify("!!!") == "untitled"


class TestFileStem:
    """doc_id may be a real-world identifier containing slashes; the filename
    derived from it must never contain a path separator."""

    def test_slashes_do_not_become_directories(self) -> None:
        document = _document(doc_id="DEMO/EXAM/2026/03")
        assert "/" not in document.file_stem
        assert document.file_stem == "demo-exam-2026-03"

    def test_the_identifier_itself_is_untouched(self) -> None:
        document = _document(doc_id="DEMO/EXAM/2026/03")
        assert document.doc_id == "DEMO/EXAM/2026/03"

    def test_ordinary_ids_pass_through(self) -> None:
        assert _document(doc_id="pce-about-the-institute").file_stem == "pce-about-the-institute"

    def test_distinct_ids_stay_distinct(self) -> None:
        assert (
            _document(doc_id="DEMO/CE/2026/07").file_stem
            != _document(doc_id="DEMO/CE/2026/08").file_stem
        )

"""Health and readiness endpoints.

/health        liveness  — is this process up? No dependencies touched.
/health/ready  readiness — are PostgreSQL, Redis, Chroma and Ollama all
                           reachable, and are the required models pulled?

/health/ready is the single command that answers "is the stack green?", and is
what scripts/verify-stack.sh calls. It returns 200 when everything is up and
503 when anything is not, so it works as a CI gate too.
"""

import asyncio
import time
from typing import Any

import httpx
import redis
from fastapi import APIRouter, Response, status

from app.core.config import settings
from app.core.logging import get_logger
from app.db.session import check_database

logger = get_logger(__name__)
router = APIRouter(tags=["health"])

PROBE_TIMEOUT_SECONDS = 5.0


def _ok(detail: str, **extra: Any) -> dict[str, Any]:
    return {"status": "up", "detail": detail, **extra}


def _fail(detail: str, **extra: Any) -> dict[str, Any]:
    return {"status": "down", "detail": detail, **extra}


async def _check_postgres() -> dict[str, Any]:
    reachable = await asyncio.to_thread(check_database)
    host = f"{settings.postgres_host}:{settings.postgres_port}"
    return _ok("SELECT 1 succeeded", host=host) if reachable else _fail("cannot connect", host=host)


async def _check_redis() -> dict[str, Any]:
    host = f"{settings.redis_host}:{settings.redis_port}"

    def _ping() -> bool:
        client = redis.Redis(
            host=settings.redis_host,
            port=settings.redis_port,
            db=settings.redis_db,
            socket_connect_timeout=PROBE_TIMEOUT_SECONDS,
        )
        try:
            return bool(client.ping())
        finally:
            client.close()

    try:
        alive = await asyncio.to_thread(_ping)
        return _ok("PONG", host=host) if alive else _fail("no PONG", host=host)
    except Exception as exc:
        return _fail(f"{type(exc).__name__}: {exc}", host=host)


async def _check_chroma() -> dict[str, Any]:
    """Chroma moved its heartbeat from /api/v1 to /api/v2; accept either."""
    base = settings.chroma_url
    async with httpx.AsyncClient(timeout=PROBE_TIMEOUT_SECONDS) as client:
        for version in ("v2", "v1"):
            try:
                response = await client.get(f"{base}/api/{version}/heartbeat")
                if response.status_code == 200:
                    return _ok(f"heartbeat via /api/{version}", host=base)
            except Exception:  # noqa: S110 - try the other API version
                continue
    return _fail("no heartbeat on /api/v2 or /api/v1", host=base)


async def _check_ollama() -> dict[str, Any]:
    """Up is not enough — report whether the two required models are pulled."""
    base = settings.ollama_base_url
    required = [settings.ollama_generator_model, settings.ollama_judge_model]

    try:
        async with httpx.AsyncClient(timeout=PROBE_TIMEOUT_SECONDS) as client:
            response = await client.get(f"{base}/api/tags")
            response.raise_for_status()
            available = [m.get("name", "") for m in response.json().get("models", [])]
    except Exception as exc:
        return _fail(f"{type(exc).__name__}: {exc}", host=base, required_models=required)

    missing = [m for m in required if m not in available]
    if missing:
        return _fail(
            "server up, required models not pulled",
            host=base,
            available_models=available,
            missing_models=missing,
            hint="docker compose up ollama-init   (or: ollama pull " + missing[0] + ")",
        )
    return _ok("server up, all required models present", host=base, available_models=available)


@router.get("/health", summary="Liveness probe")
async def health() -> dict[str, Any]:
    """Is the API process alive? Deliberately touches no dependency."""
    return {
        "status": "ok",
        "service": settings.app_name,
        "environment": settings.app_env,
        "version": "0.1.0",
    }


@router.get("/health/ready", summary="Readiness probe across all dependencies")
async def readiness(response: Response) -> dict[str, Any]:
    """Probe every dependency in parallel and report a per-service verdict."""
    started = time.perf_counter()

    names = ("postgres", "redis", "chroma", "ollama")
    results = await asyncio.gather(
        _check_postgres(),
        _check_redis(),
        _check_chroma(),
        _check_ollama(),
        return_exceptions=True,
    )

    checks: dict[str, Any] = {}
    for name, result in zip(names, results, strict=True):
        if isinstance(result, BaseException):
            checks[name] = _fail(f"probe raised {type(result).__name__}: {result}")
        else:
            checks[name] = result

    all_up = all(c["status"] == "up" for c in checks.values())
    if not all_up:
        response.status_code = status.HTTP_503_SERVICE_UNAVAILABLE
        logger.warning(
            "readiness_failed",
            down=[n for n, c in checks.items() if c["status"] != "up"],
        )

    return {
        "status": "ready" if all_up else "not_ready",
        "checks": checks,
        "elapsed_ms": round((time.perf_counter() - started) * 1000, 1),
    }

"""Phase 0 acceptance tests.

These prove the scaffold is wired correctly without needing Docker: the app
imports, settings load, routes are registered, and the readiness endpoint
degrades honestly (503 with a per-service verdict) rather than crashing when
dependencies are absent.
"""

import pytest
from fastapi.testclient import TestClient

from app.core.config import Settings, get_settings


class TestLiveness:
    def test_health_returns_ok(self, client: TestClient) -> None:
        response = client.get("/health")
        assert response.status_code == 200
        assert response.json()["status"] == "ok"

    def test_health_does_not_touch_dependencies(self, client: TestClient) -> None:
        """Liveness must stay green even with every backing service down."""
        assert client.get("/health").status_code == 200

    def test_root_banner(self, client: TestClient) -> None:
        body = client.get("/").json()
        assert body["health"] == "/health"
        assert "phase" in body

    def test_request_id_header_is_echoed(self, client: TestClient) -> None:
        response = client.get("/health", headers={"X-Request-ID": "test-trace-123"})
        assert response.headers["X-Request-ID"] == "test-trace-123"
        assert "X-Response-Time-ms" in response.headers


class TestReadiness:
    def test_reports_all_four_dependencies(self, client: TestClient) -> None:
        """Whether up or down, the shape of the report is fixed."""
        body = client.get("/health/ready").json()
        assert set(body["checks"]) == {"postgres", "redis", "chroma", "ollama"}
        for check in body["checks"].values():
            assert check["status"] in {"up", "down"}

    def test_returns_503_when_a_dependency_is_down(self, client: TestClient) -> None:
        """With no services running, readiness must fail loudly, not silently."""
        response = client.get("/health/ready")
        body = response.json()
        if body["status"] == "ready":
            pytest.skip("live services are running; the failure path is untestable here")
        assert response.status_code == 503


class TestSettings:
    def test_database_url_is_composed_from_parts(self) -> None:
        s = Settings(
            postgres_user="u",
            postgres_password="p",
            postgres_host="h",
            postgres_port=1234,
            postgres_db="d",
        )
        assert s.database_url == "postgresql+psycopg://u:p@h:1234/d"

    def test_cors_origins_parse_from_comma_separated_string(self) -> None:
        s = Settings(cors_origins="http://a.test, http://b.test ,")
        assert s.cors_origin_list == ["http://a.test", "http://b.test"]

    def test_settings_are_cached(self) -> None:
        assert get_settings() is get_settings()

    def test_ablation_flags_exist_for_every_innovation(self) -> None:
        """Turning all five off yields configuration C0, the naive baseline."""
        s = Settings()
        for flag in (
            s.rag_structure_aware_chunking,
            s.rag_hybrid_retrieval,
            s.rag_reranking,
            s.rag_agentic_layer,
            s.rag_verification,
        ):
            assert isinstance(flag, bool)

{
  "extends": ["next/core-web-vitals"]
}

/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/building-your-application/configuring/typescript for more information.

/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
  // The portal renders on the server and talks to FastAPI over the container
  // network, so no API routes are proxied and no images are optimised through
  // a remote loader. Keeping both off means the build has no network
  // dependency beyond npm install.
  images: { unoptimized: true },
};

export default nextConfig;

/** @type {import('postcss-load-config').Config} */
const config = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

export default config;

import { redirect } from "next/navigation";
import type { Metadata } from "next";

import { SignInForm } from "@/components/admin/sign-in-form";
import { isSignedIn } from "@/lib/admin";

export const metadata: Metadata = { title: "Administrator sign-in", robots: { index: false } };

export default function AdminLoginPage() {
  if (isSignedIn()) redirect("/admin");

  return (
    <div className="container-page max-w-md py-20">
