import { cookies } from "next/headers";

import { API_BASE_URL } from "@/lib/api";
import { ADMIN_COOKIE } from "@/lib/admin";

/**
 * Starts an index rebuild, with the session cookie exchanged for a bearer token
 * server-side.
 *
 * The typed `REBUILD` confirmation is *not* enforced here. It is enforced by
 * the API, and adding a second check in the browser would create two places
 * that decide when an index may be destroyed — one of which an attacker
 * controls. The browser's job is to make the requirement visible; the server's
 * job is to be the requirement.
 */
export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  const token = cookies().get(ADMIN_COOKIE)?.value;
  if (!token) return Response.json({ detail: "not signed in" }, { status: 401 });

  const body = await request.text();

  try {
    const upstream = await fetch(`${API_BASE_URL}/admin/index/rebuild`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
      body,
      cache: "no-store",
    });
    const payload = await upstream.json().catch(() => ({}));
    return Response.json(payload, { status: upstream.status });
  } catch {
    return Response.json(
      { detail: `could not reach the API at ${API_BASE_URL}` },
      { status: 503 },
    );
  }
}

import { cookies } from "next/headers";

import { API_BASE_URL } from "@/lib/api";

/**
 * The admin session, held in an httpOnly cookie.
 *
 * The obvious approach — take the token pair from `/auth/login` and keep it in
 * `localStorage` — puts a credential that grants administrative access into a
 * place every script on the page can read. One cross-site scripting hole
 * anywhere in the portal would then hand an attacker an admin token, and this
 * application renders content that ultimately comes from a crawler.
 *
 * Instead the browser never sees the token. This route exchanges credentials
 * with FastAPI server-side and stores the access token in an httpOnly,
 * sameSite cookie; server components read it back and call the API with it.
 * JavaScript in the page cannot read it, so an injected script cannot steal it.
 *
 * The trade-off is honest: the refresh token is discarded rather than stored,
 * so a session lasts exactly as long as one access token — thirty minutes by
 * default — and then requires signing in again. For a console used
 * occasionally by one administrator that is the right side of the trade.
 */
export const dynamic = "force-dynamic";

const COOKIE = "pce_admin";

export async function POST(request: Request): Promise<Response> {
  let credentials: unknown;
  try {
    credentials = await request.json();
  } catch {
    return Response.json({ detail: "expected a JSON body" }, { status: 400 });
  }

  let upstream: Response;
  try {
    upstream = await fetch(`${API_BASE_URL}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(credentials),
      cache: "no-store",
    });
  } catch {
    return Response.json(
      { detail: `could not reach the API at ${API_BASE_URL}` },
      { status: 503 },
    );
  }

  if (!upstream.ok) {
    // Passed through unchanged. The API answers every login failure with one
    // message on purpose — distinguishing "no such account" from "wrong
    // password" would hand back the account-enumeration oracle it avoids.
    const payload = (await upstream.json().catch(() => ({}))) as { detail?: string };
    return Response.json(
      { detail: payload.detail ?? "sign-in failed" },
      { status: upstream.status },
    );
  }

  const tokens = (await upstream.json()) as { access_token: string; expires_in: number };

  cookies().set({
    name: COOKIE,
    value: tokens.access_token,
    httpOnly: true,
    sameSite: "lax",
    path: "/",
    // Matches the token's own lifetime, so the cookie cannot outlive the
    // credential it carries and leave the console appearing signed in.
    maxAge: tokens.expires_in,
    secure: process.env.NODE_ENV === "production",
  });

  return Response.json({ ok: true });
}

export async function DELETE(): Promise<Response> {
  cookies().delete(COOKIE);
  return Response.json({ ok: true });
}

import { API_BASE_URL } from "@/lib/api";

/**
 * Proxies the answer stream from FastAPI to the browser.
 *
 * The question could be posted to the API directly — CORS already allows
 * localhost:3000 — but proxying is better here for three reasons. The API host
 * stays server-side, so the portal works unchanged if FastAPI is ever on a
 * private network. Everything arrives from one origin, so there is no preflight
 * on the way to a long-lived stream. And the browser needs no build-time
 * knowledge of where the backend lives.
 *
 * The upstream body is handed straight through rather than read and re-emitted.
 * Buffering it here would collect the whole answer before sending anything,
 * which is precisely the behaviour SSE exists to avoid: under C5 a user would
 * stare at nothing for three hundred seconds and then get everything at once.
 */
export const dynamic = "force-dynamic";
export const runtime = "nodejs";

export async function POST(request: Request): Promise<Response> {
  const body = await request.text();

  let upstream: Response;
  try {
    upstream = await fetch(`${API_BASE_URL}/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body,
      cache: "no-store",
    });
  } catch {
    return sseError(`could not reach the API at ${API_BASE_URL}`);
  }

  // A failure before the stream opens still has a status code, so it arrives
  // as JSON rather than as events. Translating it into a single `error` event
  // means the client has one failure path instead of two.
  if (!upstream.ok || !upstream.body) {
    let detail = `the API answered ${upstream.status}`;
    try {
      const payload = (await upstream.json()) as { detail?: unknown };
      if (typeof payload.detail === "string") detail = payload.detail;
    } catch {
      /* keep the status-code message */
    }
    return sseError(detail);
  }

  return new Response(upstream.body, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      // no-transform matters as much as no-cache: a compressing proxy would
      // buffer the stream to compress it.
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
    },
  });
}

function sseError(message: string): Response {
  const body = `event: error\ndata: ${JSON.stringify({ message })}\n\n`;
  return new Response(body, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
    },
  });
}

