import { cookies } from "next/headers";

import { API_BASE_URL } from "@/lib/api";
import type { Result } from "@/lib/api";

/**
 * Server-side calls to the admin API, authenticated from the session cookie.
 *
 * Every function here reads the cookie itself rather than taking a token as an
 * argument. That is deliberate: a token passed around as a parameter is a
 * token that can be logged, serialised into a server-component payload, or
 * handed to a client component by accident. Keeping it inside this module
 * means the only thing that ever crosses to the browser is the data.
 */

const COOKIE = "pce_admin";

export const ADMIN_COOKIE = COOKIE;

export interface CorpusAgreement {
  manifest_documents?: number;
  database_documents?: number;
  agree?: boolean;
  difference?: string;
  action?: string;
  error?: string;
}

export interface AdminCorpus {
  database: {
    documents: number;
    real: number;
    demo: number;
    real_share: number | null;
    sections: number;
    by_category: Record<string, number>;
  };
  corpus_agreement: CorpusAgreement;
  index: {
    dense?: { name: string; vectors: number };
    sparse?: { name: string; entries: number };
    error?: string;
  };
  chunk_table: { rows: number; note: string };
  reference_data: Record<string, number>;
}

export interface EvaluationRun {
  config: string;
  questions: number;
  has_summary: boolean;
  modified: string;
  verification_verdicts: Record<string, number> | null;
  agent_stop_reasons: Record<string, number> | null;
}

export interface RebuildStatus {
  running: boolean;
  config: string | null;
  started_at: string | null;
  finished_at: string | null;
  result: string | null;
  error: string | null;
}

export function adminToken(): string | undefined {
  return cookies().get(COOKIE)?.value;
}

export function isSignedIn(): boolean {
  return Boolean(adminToken());
}

async function adminGet<T>(path: string): Promise<Result<T>> {
  const token = adminToken();
  if (!token) return { ok: false, error: "not signed in" };

  try {
    const response = await fetch(`${API_BASE_URL}${path}`, {
      headers: { Authorization: `Bearer ${token}`, Accept: "application/json" },
      cache: "no-store",
    });

    if (response.status === 401) return { ok: false, error: "session expired" };
    if (response.status === 403) return { ok: false, error: "this account is not an administrator" };
    if (!response.ok) return { ok: false, error: `the API answered ${response.status}` };
    return { ok: true, data: (await response.json()) as T };
  } catch {
    return { ok: false, error: `could not reach the API at ${API_BASE_URL}` };
  }
}

export const admin = {
  corpus: () => adminGet<AdminCorpus>("/admin/corpus"),
  evaluations: () => adminGet<{ root: string; runs: EvaluationRun[] }>("/admin/evaluations"),
  indexStatus: () => adminGet<RebuildStatus>("/admin/index/status"),
  me: () => adminGet<{ id: string; email: string; role: string }>("/auth/me"),
};

/**
 * The portal's only route to the backend.
 *
 * Two decisions worth stating.
 *
 * **Failure is a value, not an exception.** Every call returns
 * `{ data }` or `{ error }`. A portal whose API is briefly down should render
 * a page that says so, not a stack trace or a blank screen — this is a system
 * that gets demonstrated live on a laptop running five containers, and the
 * realistic failure is "the API is still starting", which deserves a sentence
 * rather than a crash.
 *
 * **Nothing is cached.** The corpus and its counts change whenever the seed
 * runs, and a portal showing yesterday's document count while the admin panel
 * shows today's is exactly the drift this project has spent two phases
 * chasing. Correctness beats a fast second paint here.
 */

import type {
  CompareIndex,
  Comparison,
  CorpusDocument,
  CorpusStats,
  Department,
  DepartmentDetail,
  Paged,
  Program,
} from "./types";

const BASE =
  process.env.API_BASE_URL ??
  process.env.NEXT_PUBLIC_API_BASE_URL ??
  "http://localhost:8000/api/v1";

/**
 * Discriminated on a literal `ok`, not on whether `error` is set.
 *
 * The obvious shape — `{ data: T } | { error: string }` — does not narrow.
 * `if (result.error)` is a truthiness test, and `""` is a valid `string`, so
 * TypeScript cannot rule out the error branch and `data` stays possibly
 * undefined at every use site. A literal `true`/`false` tag is the only thing
 * the compiler can eliminate a branch on.
 */
export type Result<T> = { ok: true; data: T } | { ok: false; error: string };

async function get<T>(path: string, params?: Record<string, string | number | undefined>): Promise<Result<T>> {
  const url = new URL(`${BASE}${path}`);
  for (const [key, value] of Object.entries(params ?? {})) {
    if (value !== undefined && value !== "") url.searchParams.set(key, String(value));
  }

  try {
    const response = await fetch(url.toString(), {
      cache: "no-store",
      headers: { Accept: "application/json" },
    });

    if (response.status === 404) return { ok: false, error: "not found" };
    if (!response.ok) {
      return { ok: false, error: `the API answered ${response.status} for ${path}` };
    }
    return { ok: true, data: (await response.json()) as T };
  } catch {
    // Almost always the API container not being up yet. Naming the address is
    // the single most useful thing to put on the screen, because the fix is
    // either starting it or correcting API_BASE_URL.
    return { ok: false, error: `could not reach the API at ${BASE}` };
  }
}

// The portal router is mounted with `APIRouter(tags=["portal"])` — no prefix of
// its own — so its routes sit directly under the API prefix. There is no
// `/portal` segment, however much the module name suggests one.
export const api = {
  departments: () => get<{ total: number; items: Department[] }>("/departments"),

  department: (slug: string) => get<DepartmentDetail>(`/departments/${encodeURIComponent(slug)}`),

  programs: (level?: string) => get<{ total: number; items: Program[] }>("/programs", { level }),

  corpusStats: () => get<CorpusStats>("/corpus/stats"),

  /**
   * Faculty pages are served from the document corpus rather than a `faculty`
   * table. The table exists in the schema but nothing populates it; the
   * crawled directory pages do, and pretending otherwise would mean an empty
   * page where a university site always has its most-visited one.
   */
  documents: (options: {
    category?: string;
    search?: string;
    limit?: number;
    offset?: number;
  }) => get<Paged<CorpusDocument>>("/corpus/documents", options),

  compareIndex: () => get<CompareIndex>("/compare"),

  compareQuestion: (questionId: string, configs: string[]) =>
    get<Comparison>(`/compare/${encodeURIComponent(questionId)}`, {
      configs: configs.join(","),
    }),
};

export const API_BASE_URL = BASE;

/**
 * Accepts anything carrying a label and a URL, so the live answer stream and
 * the recorded evaluation runs share one implementation. Two prettifiers over
 * one label format would drift.
 */
interface Labelled {
  label: string;
  url: string | null;
}

/**
 * Make a citation label readable, without changing what it refers to.
 *
 * The backend builds labels as `{document_title} > {heading} > page N`, and
 * the logic is right. The trouble is `document_title`: for a crawled PDF it is
 * derived from the URL path at parse time, so
 * `.../uploads/2023/07/1-Courses-Intake.pdf` becomes the document title
 * "Wp Content Uploads 2023 07 1 Courses Intake.Pdf" — accurate, and unreadable
 * beside an answer.
 *
 * **This is deliberately a display fix and not a data fix.** Correcting the
 * title at parse time would mean re-parsing the corpus, which re-chunks it,
 * which invalidates the index every evaluation run was computed against. A
 * cosmetic problem is not worth seven configurations and 140 questions.
 *
 * So: the same document, the same section, the same page — spelled better. The
 * unmodified label is kept and shown on hover, so what the pipeline actually
 * recorded stays inspectable rather than being quietly replaced.
 */
export interface DisplaySource {
  title: string;
  section: string | null;
  raw: string;
}

export function displaySource(source: Labelled): DisplaySource {
  const raw = source.label;

  const parts = raw
    .replace(/\s*\[DEMO DATA\]\s*$/i, "")
    .split(">")
    .map((part) => part.trim())
    .filter(Boolean);

  // `page N` is dropped from the section path because the page is rendered as
  // its own field; leaving it here would print it twice.
  const section = parts.slice(1).filter((part) => !/^page\s+\d+$/i.test(part));

  const fallback = parts[0] ?? raw;
  const title = isPdf(source.url) ? (titleFromUrl(source.url) ?? fallback) : fallback;

  return {
    title,
    section: section.length > 0 ? section.join(" › ") : null,
    raw,
  };
}

function isPdf(url: string | null): boolean {
  return typeof url === "string" && /\.pdf(\?|#|$)/i.test(url);
}

function titleFromUrl(url: string | null): string | null {
  if (!url) return null;

  const file = url.split("?")[0].split("#")[0].split("/").filter(Boolean).pop();
  if (!file) return null;

  let name: string;
  try {
    name = decodeURIComponent(file);
  } catch {
    name = file;
  }

  name = name
    .replace(/\.pdf$/i, "")
    .replace(/[-_]+/g, " ")
    // A leading ordinal ("1 Courses Intake") is a filename artefact, not part
    // of the document's name.
    .replace(/^\d+[\s.)-]*/, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!name) return null;
  return `${name} (PDF)`;
}

/**
 * Types and a parser for the answer stream.
 *
 * The event contract is defined by `rag/streaming.py` and documented on
 * `answer_events`. One rule governs everything here and is worth restating,
 * because a client that gets it wrong silently undoes C5:
 *
 *   **The `answer` event is authoritative; `token` events are a preview.**
 *
 * Verification runs *after* generation, so by the time it withholds an
 * unsupported answer the user has already watched that text arrive token by
 * token. The final `answer` event carries the text the system stands behind —
 * which may be a refusal replacing everything shown so far. Rendering the
 * accumulated tokens as the answer would display exactly the claim the system
 * decided not to make.
 */

export interface SourceRef {
  marker: string;
  label: string;
  url: string | null;
  page: number | null;
  is_demo: boolean;
  chunk_id: string;
}

export interface StageEvent {
  stage: "retrieval" | "agent" | "generation" | "verification" | string;
  status?: "started" | "finished" | string;
  config?: string;
  passages?: number;
  reranked_to?: number | null;
  elapsed_ms?: number;
  iteration?: number;
  query?: string;
  new_passages?: number;
  decision?: string;
  stop_reason?: string;
  verdict?: string;
  checked?: number;
  unsupported?: number;
  support_rate?: number;
  refused?: boolean;
}

export interface Verification {
  verdict: string;
  support_rate: number | null;
  unsupported_sentences: string[];
  refused: boolean;
  withheld_text: string | null;
}

export interface AnswerPayload {
  answer: string;
  config: string;
  model: string;
  used_demo_sources: boolean;
  latency_ms: number;
  retrieval_ms: number;
  generation_ms: number;
  verification?: Verification;
}

export type StreamEvent =
  | { name: "stage"; data: StageEvent }
  | { name: "sources"; data: { sources: SourceRef[]; contains_demo: boolean } }
  | { name: "token"; data: { text: string } }
  | { name: "answer"; data: AnswerPayload }
  | { name: "done"; data: { latency_ms: number } }
  | { name: "error"; data: { message: string } };

/**
 * Turn a byte stream of Server-Sent Events into parsed events.
 *
 * Written by hand rather than using `EventSource`, which only issues GET
 * requests — the question goes in a POST body. The buffering matters: a chunk
 * boundary can fall anywhere, including the middle of a JSON payload, so
 * events are only emitted once a complete `\n\n`-terminated block has arrived.
 */
export async function* readEventStream(
  body: ReadableStream<Uint8Array>,
  signal?: AbortSignal,
): AsyncGenerator<StreamEvent> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  try {
    while (true) {
      if (signal?.aborted) return;
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });

      let split = buffer.indexOf("\n\n");
      while (split !== -1) {
        const block = buffer.slice(0, split);
        buffer = buffer.slice(split + 2);
        const event = parseBlock(block);
        if (event) yield event;
        split = buffer.indexOf("\n\n");
      }
    }
  } finally {
    reader.releaseLock();
  }
}

function parseBlock(block: string): StreamEvent | null {
  let name = "message";
  const dataLines: string[] = [];

  for (const line of block.split("\n")) {
    if (line.startsWith("event:")) name = line.slice(6).trim();
    else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
  }

  if (dataLines.length === 0) return null;
  try {
    return { name, data: JSON.parse(dataLines.join("\n")) } as StreamEvent;
  } catch {
    // A malformed payload is dropped rather than thrown: one bad event must
    // not abort a stream whose remaining events are fine.
    return null;
  }
}

